// Loads the rules data generated by scripts/build-srd.mjs from /data/srd/*.json.
// Each file is fetched once and cached for the rest of the visit.

const cache = new Map();

export const DATASETS = [
  'spells',
  'monsters',
  'magic-items',
  'feats',
  'backgrounds',
  'species',
  'classes',
  'equipment',
  'glossary',
  'chapters',
];

export function loadSrd(name) {
  if (!DATASETS.includes(name) && name !== 'index') return Promise.reject(new Error(`Unknown dataset: ${name}`));
  if (!cache.has(name)) {
    const url = `${import.meta.env.BASE_URL}data/srd/${name}.json`;
    cache.set(
      name,
      fetch(url).then((r) => {
        if (!r.ok) throw new Error(`Could not load ${name} (${r.status})`);
        return r.json();
      }),
    );
    cache.get(name).catch(() => cache.delete(name));
  }
  return cache.get(name);
}

export const ABILITY_NAMES = {
  str: 'Strength',
  dex: 'Dexterity',
  con: 'Constitution',
  int: 'Intelligence',
  wis: 'Wisdom',
  cha: 'Charisma',
};

export function formatMod(n) {
  if (n == null) return '';
  return n >= 0 ? `+${n}` : `−${Math.abs(n)}`;
}

export function spellLevelLabel(level) {
  if (level === 0) return 'Cantrip';
  const suffix = level === 1 ? 'st' : level === 2 ? 'nd' : level === 3 ? 'rd' : 'th';
  return `${level}${suffix} level`;
}
